tool_input.command:
cat > _p.py <<'EOF'
p = "src/usine/ui/vues.py"
s = open(p, encoding="utf-8").read()
a = '    bouton_mode: VueBouton\n    journal'
assert a in s
s = s.replace(a, '    bouton_mode: VueBouton\n    mode_cible: Literal["repli", "reel"]\n    """Mode que `POST /api/mode` demande au clic du bouton de mode."""\n    journal', 1)
open(p, "w", encoding="utf-8").write(s)
p = "src/usine/ui/chaine.py"
s = open(p, encoding="utf-8").read()
a = "            bouton_mode=bouton_mode,\n"
assert a in s
s = s.replace(a, a + '            mode_cible="reel" if repli else "repli",\n', 1)
open(p, "w", encoding="utf-8").write(s)
p = "src/usine/ui/statique/cadre.js"
s = open(p, encoding="utf-8").read()
a = "  // Aux écrans de 7.14 à 7.16"
assert a in s
s = s.replace(a, '''  // Écriture JSON (les deux seules routes POST) : rend le statut et le corps, ou null si le
  // serveur ne répond pas (bandeau d'erreur unique).
  function envoyer(chemin, corps) {
    var options = { method: "POST", headers: { Accept: "application/json" } };
    if (corps !== undefined) {
      options.headers["Content-Type"] = "application/json";
      options.body = JSON.stringify(corps);
    }
    return fetch(chemin, options)
      .then(function (reponse) {
        return reponse.json().then(
          function (donnees) {
            return { statut: reponse.status, donnees: donnees };
          },
          function () {
            return { statut: reponse.status, donnees: null };
          }
        );
      })
      .then(function (resultat) {
        retirerBandeau("injoignable");
        return resultat;
      })
      .catch(function () {
        signalerServeurInjoignable();
        return null;
      });
  }

''' + a, 1)
s = s.replace("    appeler: appeler,\n", "    appeler: appeler,\n    envoyer: envoyer,\n    afficherCadre: afficherCadre,\n    rafraichirCadre: chargerCadre,\n", 1)
open(p, "w", encoding="utf-8").write(s)
EOF
uv run python _p.py 2>&1 | grep -v warning; rm _p.py
